import sys

def main():
    m = input().strip()

    n = len(m)

    # Check if the mask is valid
    if m[0] == '#' or m[-1] == '#':
        print(-1)
        return

    # Find segments of filled cells
    segments = []
    current_segment = 0
    for i in range(n):
        if m[i] == '#':
            current_segment += 1
        else:
            if current_segment > 0:
                segments.append(current_segment)
                current_segment = 0

    # If there's a segment at the end
    if current_segment > 0:
        segments.append(current_segment)

    # Check if there are any filled cells next to each other
    for i in range(1, n):
        if m[i] == '#' and m[i-1] == '#':
            print(-1)
            return

    # Output the result
    k = len(segments)
    print(k)
    print(' '.join(map(str, segments)))

if __name__ == "__main__":
    main()
